   618	fn windowsCreateCommandLine(allocator: mem.Allocator, argv: []const []const u8) ![:0]u8 {
   619	    var buf: std.Io.Writer.Allocating = .init(allocator);
   620	    defer buf.deinit();
   621	    const writer = &buf.writer;
   622	
   623	    for (argv, 0..) |arg, arg_i| {
   624	        if (arg_i != 0) try writer.writeByte(' ');
   625	        if (mem.indexOfAny(u8, arg, " \t\n\"") == null) {
   626	            try writer.writeAll(arg);
   627	            continue;
   628	        }
   629	        try writer.writeByte('"');
   630	        var backslash_count: usize = 0;
   631	        for (arg) |byte| {
   632	            switch (byte) {
   633	                '\\' => backslash_count += 1,
   634	                '"' => {
   635	                    try writer.splatByteAll('\\', backslash_count * 2 + 1);
   636	                    try writer.writeByte('"');
   637	                    backslash_count = 0;
   638	                },
   639	                else => {
   640	                    try writer.splatByteAll('\\', backslash_count);
   641	                    try writer.writeByte(byte);
   642	                    backslash_count = 0;
   643	                },
   644	            }
   645	        }
   646	        try writer.splatByteAll('\\', backslash_count * 2);
   647	        try writer.writeByte('"');
   648	    }
   649	
   650	    return buf.toOwnedSliceSentinel(0);
   651	}
